// Generated by GitHub Copilot - Oct-23-2026
import { useEffect, useState } from 'react';
import { FLAVORS, LANGUAGES } from '../../data';
import {
  addDispenser,
  getTenant,
  isValidIPv4,
  isValidPort,
  listDispensers,
  pickActiveDispenser,
  removeDispenser,
  saveTenant,
  saveTrays,
  testConnection,
} from '../../services/tenant';
import type { Dispenser, TenantSettings, TenantUser, Tray } from '../../types';
import JellyBean from '../../components/JellyBean';
import UsersModal from './UsersModal';
import TraysModal from './TraysModal';

const flavorById = new Map(FLAVORS.map((f) => [f.id, f]));

/** Internal admin: tenant settings, users, and Wi-Fi dispensers with tray configuration. */
export default function Tenant() {
  const [tenant, setTenant] = useState<TenantSettings | null>(null);
  const [draft, setDraft] = useState<TenantSettings | null>(null);
  const [editing, setEditing] = useState(false);
  const [saving, setSaving] = useState(false);
  const [usersOpen, setUsersOpen] = useState(false);
  const [dispensers, setDispensers] = useState<Dispenser[]>([]);
  const [pinging, setPinging] = useState<string | null>(null);
  const [traysFor, setTraysFor] = useState<Dispenser | null>(null);

  const [newName, setNewName] = useState('');
  const [newIp, setNewIp] = useState('');
  const [newPort, setNewPort] = useState('80');
  const [addError, setAddError] = useState('');

  useEffect(() => {
    let cancelled = false;
    Promise.all([getTenant(), listDispensers()]).then(([t, d]) => {
      if (cancelled) return;
      setTenant(t);
      setDraft(t);
      setDispensers(d);
    });
    return () => {
      cancelled = true;
    };
  }, []);

  const replaceDispenser = (d: Dispenser) => setDispensers((list) => list.map((x) => (x.id === d.id ? d : x)));

  const persistTenant = async (next: TenantSettings) => {
    setSaving(true);
    const saved = await saveTenant(next);
    setTenant(saved);
    setDraft(saved);
    setSaving(false);
  };

  const onSaveSettings = async () => {
    if (!draft || !draft.name.trim()) return;
    await persistTenant({ ...draft, name: draft.name.trim() });
    setEditing(false);
  };

  const onSaveUsers = async (users: TenantUser[]) => {
    if (!tenant) return;
    await persistTenant({ ...tenant, users });
    setUsersOpen(false);
  };

  const onAddDispenser = async () => {
    const port = Number(newPort);
    if (!newName.trim()) return setAddError('Give the dispenser a name.');
    if (!isValidIPv4(newIp)) return setAddError('Enter a valid IPv4 address, e.g. 192.168.1.42.');
    if (!isValidPort(port)) return setAddError('Port must be between 1 and 65535.');
    try {
      const d = await addDispenser({ name: newName, ip: newIp, port });
      setDispensers((list) => [...list, d]);
      setNewName('');
      setNewIp('');
      setNewPort('80');
      setAddError('');
    } catch (e) {
      setAddError(e instanceof Error ? e.message : 'Could not add dispenser.');
    }
  };

  const onPing = async (id: string) => {
    setPinging(id);
    replaceDispenser(await testConnection(id));
    setPinging(null);
  };

  const onRemove = async (d: Dispenser) => {
    if (!window.confirm(`Remove ${d.name} (${d.ip})?`)) return;
    await removeDispenser(d.id);
    setDispensers((list) => list.filter((x) => x.id !== d.id));
  };

  const onSaveTrays = async (trays: Tray[]) => {
    if (!traysFor) return;
    replaceDispenser(await saveTrays(traysFor.id, trays));
    setTraysFor(null);
  };

  return (
    <div className="page page--dark">
      <header className="admin-bar">
        <span className="admin-bar__title">JAIME Admin</span>
        <a className="admin-bar__link" href="#/">
          <span aria-hidden="true">←</span> Launchpad
        </a>
      </header>

      <main id="main" className="admin">
        <h1 className="admin__title">Tenant Settings</h1>

        {!tenant || !draft ? (
          <p role="status" className="admin__muted">
            Loading...
          </p>
        ) : (
          <div className="admin__grid">
            <section className="ml-card" aria-labelledby="tenant-heading">
              <div className="ml-card__head">
                <h2 id="tenant-heading">Tenant</h2>
                {!editing && (
                  <button type="button" className="icon-btn" aria-label="Edit tenant settings" onClick={() => setEditing(true)}>
                    ✎
                  </button>
                )}
              </div>

              <form
                className="ml-form"
                onSubmit={(e) => {
                  e.preventDefault();
                  onSaveSettings();
                }}
              >
                <label className="ml-field">
                  <span>Tenant name</span>
                  <input
                    type="text"
                    value={draft.name}
                    maxLength={80}
                    required
                    disabled={!editing}
                    onChange={(e) => setDraft({ ...draft, name: e.target.value })}
                  />
                </label>
                <label className="ml-field">
                  <span>Language</span>
                  <select value={draft.language} disabled={!editing} onChange={(e) => setDraft({ ...draft, language: e.target.value })}>
                    {LANGUAGES.map((l) => (
                      <option key={l} value={l}>
                        {l}
                      </option>
                    ))}
                  </select>
                </label>
                <label className="ml-check">
                  <input
                    type="checkbox"
                    checked={draft.devicesEnabled}
                    disabled={!editing}
                    onChange={(e) => setDraft({ ...draft, devicesEnabled: e.target.checked })}
                  />
                  <span>Enable devices</span>
                </label>
                {editing && (
                  <div className="ml-form__actions">
                    <button
                      type="button"
                      className="btn btn--ghost"
                      onClick={() => {
                        setDraft(tenant);
                        setEditing(false);
                      }}
                    >
                      Cancel
                    </button>
                    <button type="submit" className="btn btn--primary btn--purple" disabled={saving || !draft.name.trim()}>
                      {saving ? 'Saving...' : 'Save'}
                    </button>
                  </div>
                )}
              </form>

              <div className="ml-card__footer">
                <p>
                  <span className="admin__muted">Users</span> <strong>{tenant.users.length}</strong>
                </p>
                <button type="button" className="btn btn--primary btn--purple" onClick={() => setUsersOpen(true)}>
                  Add / Manage Users
                </button>
              </div>
            </section>

            <section className="ml-card" aria-labelledby="dispensers-heading">
              <div className="ml-card__head">
                <h2 id="dispensers-heading">Dispensers</h2>
              </div>

              {dispensers.length === 0 && <p className="admin__muted">No dispensers connected yet.</p>}
              {!tenant.devicesEnabled && dispensers.length > 0 && (
                <p className="field-error">Devices are disabled, so the demo shows no flavors. Turn on &ldquo;Enable devices&rdquo;.</p>
              )}

              <ul className="dispenser-list">
                {dispensers.map((d) => {
                  const loaded = d.trays.filter((t) => t.flavorId);
                  const isActive = pickActiveDispenser(dispensers)?.id === d.id;
                  return (
                    <li key={d.id} className="dispenser">
                      <div className="dispenser__head">
                        <div>
                          <h3>
                            {d.name}
                            {isActive && <span className="demo-tag">Used by demo</span>}
                          </h3>
                          <p className="mono admin__muted">
                            {d.ip}:{d.port}
                          </p>
                        </div>
                        <span className={`status ${d.online ? 'status--on' : 'status--off'}`}>
                          <span className="status__dot" aria-hidden="true" />
                          {pinging === d.id ? 'Checking...' : d.online ? 'Online' : 'Offline'}
                        </span>
                      </div>
                      {d.lastSeen && (
                        <p className="admin__muted dispenser__seen">Last seen {new Date(d.lastSeen).toLocaleString()}</p>
                      )}

                      <ul className="tray-chips" aria-label={`${d.name} trays`}>
                        {loaded.length === 0 && <li className="admin__muted">No trays configured</li>}
                        {loaded.map((t) => {
                          const f = flavorById.get(t.flavorId!);
                          return (
                            <li key={t.slot} className="tray-chip">
                              <span className="tray-chip__slot">{t.slot}</span>
                              {f && <JellyBean color={f.color} size={28} />}
                              <span>{f?.name ?? t.flavorId}</span>
                              <span className="tray-chip__count">{t.count}</span>
                            </li>
                          );
                        })}
                      </ul>

                      <div className="dispenser__actions">
                        <button type="button" className="btn btn--ghost btn--sm" disabled={pinging === d.id} onClick={() => onPing(d.id)}>
                          Test connection
                        </button>
                        <button type="button" className="btn btn--primary btn--purple btn--sm" onClick={() => setTraysFor(d)}>
                          Configure trays
                        </button>
                        <button type="button" className="btn btn--danger btn--sm" onClick={() => onRemove(d)}>
                          Remove
                        </button>
                      </div>
                    </li>
                  );
                })}
              </ul>

              <form
                className="ml-form add-dispenser"
                aria-labelledby="add-dispenser-heading"
                noValidate
                onSubmit={(e) => {
                  e.preventDefault();
                  onAddDispenser();
                }}
              >
                <h3 id="add-dispenser-heading">Connect a dispenser over Wi-Fi</h3>
                <p className="admin__muted add-dispenser__hint">
                  Join the dispenser to the same Wi-Fi network, then enter the IP address it shows on boot.
                </p>
                <div className="add-dispenser__row">
                  <label className="ml-field">
                    <span>Name</span>
                    <input type="text" maxLength={60} value={newName} onChange={(e) => setNewName(e.target.value)} />
                  </label>
                  <label className="ml-field">
                    <span>IP address</span>
                    <input
                      type="text"
                      inputMode="decimal"
                      placeholder="192.168.1.42"
                      autoComplete="off"
                      value={newIp}
                      aria-invalid={!!addError && !isValidIPv4(newIp)}
                      onChange={(e) => setNewIp(e.target.value)}
                    />
                  </label>
                  <label className="ml-field ml-field--port">
                    <span>Port</span>
                    <input type="number" min={1} max={65535} value={newPort} onChange={(e) => setNewPort(e.target.value)} />
                  </label>
                </div>
                {addError && (
                  <p className="field-error" role="alert">
                    {addError}
                  </p>
                )}
                <div className="ml-form__actions">
                  <button type="submit" className="btn btn--primary btn--purple">
                    Add dispenser
                  </button>
                </div>
              </form>
            </section>
          </div>
        )}
      </main>

      {usersOpen && tenant && (
        <UsersModal users={tenant.users} saving={saving} onCancel={() => setUsersOpen(false)} onSave={onSaveUsers} />
      )}
      {traysFor && <TraysModal dispenser={traysFor} onCancel={() => setTraysFor(null)} onSubmit={onSaveTrays} />}
    </div>
  );
}
